import unittest
from decimal import Decimal

from kitty.errors import KittyError
from kitty.money import convert, format_cents, parse_amount, parse_positive_decimal, split


class ParseTests(unittest.TestCase):
    def test_parse_amount_valid(self):
        self.assertEqual(parse_amount("45"), 4500)
        self.assertEqual(parse_amount("45.5"), 4550)
        self.assertEqual(parse_amount("0.01"), 1)

    def test_parse_amount_rejects(self):
        for bad in ["0", "0.00", "-5", "1e3", "nan", "inf", "abc", "", "1.234", ".5", "5."]:
            with self.subTest(bad=bad), self.assertRaises(KittyError):
                parse_amount(bad)

    def test_comma_hint(self):
        with self.assertRaises(KittyError) as cm:
            parse_amount("12,50")
        self.assertIn("dot", str(cm.exception))
        with self.assertRaises(KittyError) as cm:
            parse_positive_decimal("0,92", "rate")
        self.assertIn("dot", str(cm.exception))

    def test_parse_positive_decimal(self):
        self.assertEqual(parse_positive_decimal("0.923456", "rate"), Decimal("0.923456"))
        for bad in ["0", "-1", "1e2", "x"]:
            with self.subTest(bad=bad), self.assertRaises(KittyError):
                parse_positive_decimal(bad, "rate")


class ConvertFormatTests(unittest.TestCase):
    def test_convert_half_up(self):
        self.assertEqual(convert(4500, Decimal("0.92")), 4140)
        self.assertEqual(convert(125, Decimal("0.1")), 13)  # 1.25 * 0.1 = 0.125 -> 0.13
        self.assertEqual(convert(100, Decimal("0.125")), 13)  # 0.125 -> 0.13, never 0.12
        self.assertEqual(convert(1000, Decimal("1")), 1000)

    def test_format(self):
        self.assertEqual([format_cents(c) for c in (2070, -2070, 0, -5)],
                         ["20.70", "-20.70", "0.00", "-0.05"])


class SplitTests(unittest.TestCase):
    def test_split_equal_three(self):
        self.assertEqual(split(1000, [("Alice", 1), ("Bob", 1), ("Cara", 1)]),
                         [("Alice", 334), ("Bob", 333), ("Cara", 333)])

    def test_split_shares_not_largest_remainder(self):
        self.assertEqual(split(1000, [("A", 1), ("B", 2)]), [("A", 334), ("B", 666)])

    def test_split_percent(self):
        self.assertEqual(split(1000, [("A", Decimal("33.5")), ("B", Decimal("66.5"))]),
                         [("A", 335), ("B", 665)])
        self.assertEqual(split(1001, [("A", Decimal("50")), ("B", Decimal("50"))]),
                         [("A", 501), ("B", 500)])

    def test_split_leftover_in_given_order(self):
        self.assertEqual(split(200, [("C", 1), ("A", 1), ("B", 1)]),
                         [("C", 67), ("A", 67), ("B", 66)])

    def test_split_tiny(self):
        self.assertEqual(split(1, [("A", 1), ("B", 1), ("C", 1)]),
                         [("A", 1), ("B", 0), ("C", 0)])

    def test_split_sums(self):
        r = split(4140, [("A", 3000), ("B", 1500)])
        self.assertEqual(sum(c for _, c in r), 4140)


if __name__ == "__main__":
    unittest.main()
